    double perimeter = a + b + c;

    // Incenter coordinates: weighted average by opposite side lengths
    double cx = (a * x1 + b * x2 + c * x3) / perimeter;
    double cy = (a * y1 + b * y2 + c * y3) / perimeter;

    // Triangle area via cross product
    double area = fabs((x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1)) / 2.0;

    // Inradius: r = 2 * area / perimeter
    double r = 2.0 * area / perimeter;

    printf("%.6f %.6f %.6f\n", cx, cy, r);

    return 0;
}

