public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);

        double x1 = sc.nextDouble(), y1 = sc.nextDouble();
        double x2 = sc.nextDouble(), y2 = sc.nextDouble();
        double x3 = sc.nextDouble(), y3 = sc.nextDouble();

        double a = dist(x2, y2, x3, y3); // side opposite A
        double b = dist(x1, y1, x3, y3); // side opposite B
        double c = dist(x1, y1, x2, y2); // side opposite C

        double perimeter = a + b + c;

        double cx = (a * x1 + b * x2 + c * x3) / perimeter;
        double cy = (a * y1 + b * y2 + c * y3) / perimeter;

        double area2 = Math.abs(
                x1 * (y2 - y3) +
                x2 * (y3 - y1) +
                x3 * (y1 - y2)
        ); // 2 * area

        double area = area2 / 2.0;
        double s = perimeter / 2.0;
        double r = area / s;

        System.out.printf(Locale.US, "%.10f %.10f %.10f%n", cx, cy, r);
    }

    static double dist(double x1, double y1, double x2, double y2) {
        double dx = x1 - x2;
        double dy = y1 - y2;
        return Math.sqrt(dx * dx + dy * dy);
    }
}
